import os

# Configuration
SOURCE_DIR = 'css/modules'
OUTPUT_FILE = 'src/input.css'

# Order matters for variables and base, others can be dynamic
ORDERED_BASICS = [
    'variables.css',
    'base.css'
]

def restore_css():
    print(f"--- REGEN-SYSTEM: Starting Dynamic CSS Restoration ---")
    
    if not os.path.exists(SOURCE_DIR):
        print(f"ERROR: Source directory {SOURCE_DIR} not found.")
        return

    # 1. Start with Tailwind Directives
    css_content = [
        "/* AUTOGENERATED BY REGEN-SYSTEM - DO NOT EDIT MANUALLY */",
        "@tailwind base;",
        "@tailwind components;",
        "@tailwind utilities;",
        ""
    ]
    
    # 2. Add Basics (Variables first)
    found_files = os.listdir(SOURCE_DIR)
    for basic in ORDERED_BASICS:
        if basic in found_files:
            print(f"Basics Layer: {basic}")
            path = os.path.join(SOURCE_DIR, basic)
            with open(path, 'r', encoding='utf-8') as f:
                css_content.append(f"\n/* SOURCE: {basic} */\n{f.read()}")
            found_files.remove(basic)

    # 3. Add remaining modules dynamically inside @layer components
    print(f"Components Layer: Processing {len(found_files)} modules...")
    css_content.append("\n@layer components {")
    for filename in sorted(found_files):
        if filename.endswith('.css'):
            print(f"  + {filename}")
            path = os.path.join(SOURCE_DIR, filename)
            with open(path, 'r', encoding='utf-8') as f:
                css_content.append(f"\n  /* SOURCE: {filename} */\n{f.read()}")
    css_content.append("}")

    # 4. Inject Self-Healing / Regenerative Factor Classes
    css_content.append("""
/* --- REGEN-SYSTEM: Regenerative Layer --- */
.healed-asset {
    border: 2px solid #00f2ff !important;
    animation: regenPulse 2s infinite;
}

@keyframes regenPulse {
    0% { opacity: 0.8; filter: brightness(1); }
    50% { opacity: 1; filter: brightness(1.2) drop-shadow(0 0 10px #00f2ff); }
    100% { opacity: 0.8; filter: brightness(1); }
}
""")

    # Ensure target directory exists
    os.makedirs(os.path.dirname(OUTPUT_FILE), exist_ok=True)
    
    with open(OUTPUT_FILE, 'w', encoding='utf-8') as f:
        f.write("\n".join(css_content))
        
    print(f"--- REGEN-SYSTEM: Restoration Complete. Output: {OUTPUT_FILE} ---")

if __name__ == "__main__":
    restore_css()
